// Custom Worker entry (OpenNext): edge rules first, then the generated Next.js handler.
// .open-next/worker.js is generated by `opennextjs-cloudflare build`; this file is excluded from tsconfig for that reason.
import handler from "./.open-next/worker.js";
import { esAppRedirect, isStaticSeoPath, rateLimited, redirectFor, verificationFile, type EdgeEnv } from "./lib/edge";
import { handleFx, refreshFx, type FxEnv } from "./lib/fx";
import { appStoreIsLive, comingSoonQr, rewriteStorefront, type StorefrontEnv } from "./lib/storefront";

type Env = EdgeEnv & FxEnv & StorefrontEnv & { ASSETS: { fetch(req: Request): Promise<Response> } };
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException?(): void };

const worker = {
  async fetch(req: Request, env: Env, ctx: Ctx) {
    const early = redirectFor(req, env) ?? verificationFile(req, env) ?? esAppRedirect(req);
    if (early) return early;
    const url = new URL(req.url);
    // USD/MXN FIX for the app's Cost estimator: served from KV (edge-cached), pinned under /api so both hosts answer it.
    if (url.pathname === "/api/fx") return handleFx(req, env, ctx);
    // Static guide/legal pages reach the Worker (assets.run_worker_first) only to get the legacy-host 301; serve them as assets.
    if ((req.method === "GET" || req.method === "HEAD") && isStaticSeoPath(url.pathname)) return env.ASSETS.fetch(req);
    const live = appStoreIsLive(env);
    // The QR encodes the App Store URL. Until the listing exists, don't hand out a code that 404s.
    if ((req.method === "GET" || req.method === "HEAD") && (url.pathname === "/api/app-qr" || url.pathname.startsWith("/api/app-qr/"))) {
      if (!(await live)) return comingSoonQr(req);
    }
    const limited = await rateLimited(req, env);
    if (limited) return limited;
    const res = await handler.fetch(req, env, ctx);
    return rewriteStorefront(res, await live);
  },
  // Daily refresh of the official USD/MXN FIX (DOF/Banxico) into FX_KV.
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(refreshFx(env));
  },
};
export default worker;

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
